const fmt=t=>`${t<0?'−':''}${Math.floor(Math.abs(t)/60)}:${(Math.abs(t)%60).toFixed(2).padStart(5,'0')}`;
function canvas2d(canvas,w,h){const dpr=Math.min(root.devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(w*dpr));canvas.height=Math.max(1,Math.round(h*dpr));const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);return c;}
function hex(c,x,y,r){c.beginPath();for(let i=0;i<6;i++){const a=(i*60-90)*Math.PI/180,px=x+Math.cos(a)*r,py=y+Math.sin(a)*r;if(i)c.lineTo(px,py);else c.moveTo(px,py);}c.closePath();}
