 h.open(h.header('▷ 谱面试玩 <span class="tiny-tag">实验室 · CLASSIC 6K</span>')+`<form id="playSetup" class="play-setup"><div class="play-setup-main"><p class="modal-copy">用键盘或触屏试玩本机歌曲。全时长游玩 / 局部练习均独立计分，编辑中的谱面不会被改写。</p><div class="two-fields"><label class="field">歌曲<select id="playSong">${songs.map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')}</select></label><label class="field">经典 6K 难度<select id="playChart"></select></label></div><div class="two-fields"><label class="field">游玩范围<select id="playRange"><option value="full">全时长游玩</option><option value="part">局部时长练习</option></select></label><label class="field">计分方式<select id="playMode"><option value="standard">默认模式</option><option value="professional">专业模式</option><option value="custom">自定义模式</option></select></label></div><div id="playRangeFields" class="two-fields" hidden><label class="field">开始 · 音频秒数<input id="playFrom" type="number" min="0" step="0.001" value="0"></label><label class="field">结束 · 音频秒数<input id="playTo" type="number" min="0.001" step="0.001"></label></div><p id="playSelection" class="field-hint" role="status">正在读取歌曲时长…</p><div id="playCustom" class="play-custom" hidden>${['Perfect 内档 ＜','Perfect 外档 ＜','Great ＜','Good ＜ / Miss ≥'].map((label,i)=>`<label class="field">${label}<input data-window="${i}" type="number" min="1" max="99" step="1" value="${config.custom[i]}">ms</label>`).join('')}</div><p id="playRules" class="field-hint"></p><details><summary>界面与输入校准</summary><div class="two-fields"><label class="field">音符流速<input id="playSpeed" type="number" min="1" max="12" step="0.1" value="${config.speed}" required></label><label class="field">背景亮度 · %<input id="playBrightness" type="number" min="0" max="100" value="${config.brightness}" required></label><label class="field">音量 · %<input id="playVolume" type="number" min="0" max="100" value="${config.volume}" required></label><label class="field">音画偏移 · ms<input id="playVisualOffset" type="number" min="-500" max="500" value="${config.visualOffset||0}" required></label><label class="field">输入校准 · ms<input id="playOffset" type="number" min="-500" max="500" value="${config.offset}" required></label></div><label class="range-field">打击特效强度 <output id="playHitFxValue">${config.hitFx}%</output><input id="playHitFx" type="range" min="0" max="100" step="1" value="${config.hitFx}"></label><label class="range-field">按键反馈不透明度 <output id="playPadFeedbackValue">${config.padFeedback}%</output><input id="playPadFeedback" type="range" min="0" max="100" step="1" value="${config.padFeedback}"></label><p class="field-hint">0% 关闭触控键位的按下高亮；此项不影响皮肤打击特效或实际判定。</p><p class="field-hint">音画正值让画面晚到、负值提前；输入正值把判定时间后移、负值前移。试玩始终使用原速音频；流速仅影响视觉。默认不设帧率上限，实际由浏览器和屏幕刷新率决定。</p><button id="playAutoCalibration" type="button">120 BPM · 四拍音画 / 自动输入校准</button><label class="check-line"><input id="playShowPads" type="checkbox" ${config.showPads!==false?'checked':''}>显示触控键位（关闭仅隐藏图层，判定区域保留）</label></details><h4>六个触控键位与热键</h4><p class="field-hint">点选热键后按下新键。数字行 / 小键盘数字通用；Esc 暂停。距离相对于中心，大小为独立倍率；布局会自动适配屏幕。</p><div class="two-fields play-pad-masters"><div><label class="check-line"><input id="playSyncSize" type="checkbox" ${config.syncSize?'checked':''}>全局调整大小</label><label class="field">六轨统一大小 ×<input id="playAllSize" type="number" min="0" step="any" value="${config.allSize}"></label></div><div><label class="check-line"><input id="playSyncDistance" type="checkbox" ${config.syncDistance?'checked':''}>全局调整距离</label><label class="field">六轨统一距离 ×<input id="playAllDistance" type="number" min="0" step="any" value="${config.allDistance}"></label></div></div><p class="field-hint">勾选后锁定对应的逐轨输入并同步全局数值；取消勾选可独立调整。大小、距离均接受正数；重叠时无法开始试玩。默认大小 2 倍、距离 0.9 倍。</p><div class="play-pad-table"><table><thead><tr><th>轨道</th><th>热键</th><th>距离 ×</th><th>大小 ×</th></tr></thead><tbody>${config.pads.map((p,i)=>`<tr><th scope="row">${i+1}</th><td><button type="button" class="play-bind" data-bind="${i}" aria-label="设置轨道 ${i+1} 热键">${esc(keyName(p.key))}</button></td><td><input aria-label="轨道 ${i+1} 距离" data-pad="${i}" data-property="distance" type="number" min="0" step="any" value="${p.distance}" required></td><td><input aria-label="轨道 ${i+1} 大小" data-pad="${i}" data-property="size" type="number" min="0" step="any" value="${p.size}" required></td></tr>`).join('')}</tbody></table></div></div><aside class="play-setup-aside"><div class="eyebrow">TOUCH & KEYBOARD</div><h4>六边形键位预览</h4><canvas id="playLayout" aria-label="六轨键位布局预览"></canvas><p class="field-hint">点击按钮，或手指滑入按钮边框内，都会触发一次单点操作。每次按下优先作用于本轨最早可判定的一根音符；长条可松手再接回，持续按住不会激活下一根。</p><p class="field-hint">长条：超过 80% 为 Perfect，60%～80% 为 Great，5%～60% 为 Good，其余 Miss。所有模式相同；须在头部前 100ms 至尾部后 100ms 之间重新按下；（累计有效按住时长＋一次性 200ms）÷ 原长条时长。补偿只对已激活的长条生效，多次接回不重复添加。松手时超过 80% 将立即完成 Perfect。</p><p class="field-hint">这是本地实验室成绩，不写入官方账号。触控、音响与屏幕延迟会影响实际手感，可通过输入校准调整。</p><button id="playResetLayout" type="button" class="wide">恢复默认键位</button></aside><div class="play-setup-footer"><p id="playError" role="alert"></p><button type="button" data-close>取消</button><button id="playStart" type="submit" class="primary" disabled>开始试玩 ↗ 全屏</button></div></form>`,true);
 const form=$('playSetup'),modal=$('modal'),ab=new AbortController(),cache=new Map();let selected=null,selectionToken=0,closeCalibration=null;
 function drawLayout(){if(!form.isConnected)return;const canvas=$('playLayout'),w=canvas.getBoundingClientRect().width||340,hg=360,c=canvas2d(canvas,w,hg);c.clearRect(0,0,w,hg);if(config.pads.some(p=>!Number.isFinite(p.distance)||!Number.isFinite(p.size)||p.distance<=0||p.size<=0))return;const l=sceneLayout(w,hg,h.skin(),config);root.DCPreview.drawFrame(c,h.skin(),l);drawPads(c,w,hg,config);}
 function ruleText(){const mode=$('playMode').value;config.mode=mode;$('playCustom').hidden=mode!=='custom';form.querySelectorAll('[data-window]').forEach(e=>e.disabled=mode!=='custom');const a=mode==='custom'?config.custom:P.windows(mode);$('playRules').textContent=`单点：Perfect < ${a[1]}ms（内档 < ${a[0]}ms），Great < ${a[2]}ms，Good < ${a[3]}ms，其余 Miss。两档 Perfect 均为 100 分。未操作单点在到线后 100ms 消失。`;}
 function readConfig(){for(const [id,key]of [['playSpeed','speed'],['playBrightness','brightness'],['playVolume','volume'],['playOffset','offset'],['playVisualOffset','visualOffset'],['playHitFx','hitFx'],['playPadFeedback','padFeedback']])config[key]=+$(id).value;form.querySelectorAll('[data-window]').forEach(e=>config.custom[+e.dataset.window]=+e.value);form.querySelectorAll('[data-pad]').forEach(e=>config.pads[+e.dataset.pad][e.dataset.property]=+e.value);config.showPads=$('playShowPads').checked;return validConfig(config);}
 function selectionInfo(){if(!selected)return;try{validConfig(config);const part=$('playRange').value==='part',model=P.prepare(selected.chart,{duration:selected.buffer.duration,start:part?+$('playFrom').value:null,end:part?+$('playTo').value:null});$('playSelection').textContent=`${fmt(model.start)}～${fmt(model.end)} · ${model.total.toLocaleString()} 物量 · 满分 ${model.maxScore.toLocaleString()}${selected.chart.rec?.status==='pending'?' · REC 草稿，请对照原谱核验':''}${selected.background?'':' · 无曲绘，将使用纯色背景'}`;$('playError').textContent='';$('playStart').disabled=false;}catch(e){$('playError').textContent=e.message;$('playStart').disabled=true;}}
 async function changeChart(){const token=++selectionToken;selected=null;$('playStart').disabled=true;$('playSelection').textContent='正在读取本地音频与时长…';$('playError').textContent='';try{const song=songs.find(s=>s.id===$('playSong').value),chart=song.charts.find(c=>c.id===$('playChart').value),media=h.media(song.id,chart);if(!media?.audio)throw Error('这份难度缺少音乐，请返回歌曲库导入 / 补充音频');const key=song.id+':'+chart.id;let buffer=cache.get(key);if(!buffer){buffer=media.buffer||await h.audio().decodeAudioData(media.audio.data.slice().buffer);cache.set(key,buffer);}if(token!==selectionToken||!form.isConnected)return;const snapshot=C.validateChart(chart),model=P.prepare(snapshot,{duration:buffer.duration});selected={song,chart:snapshot,buffer,background:media.background};$('playFrom').value=0;$('playTo').value=(Math.floor(model.end*1000)/1000).toFixed(3);selectionInfo();}catch(e){if(token!==selectionToken||!form.isConnected)return;$('playSelection').textContent='暂时无法开始';$('playError').textContent=e.message;}}
 function changeSong(){const song=songs.find(s=>s.id===$('playSong').value);$('playChart').innerHTML=song.charts.map(c=>`<option value="${esc(c.id)}">${esc(C.LEVELS[c.tier].name+' '+c.level+' · '+c.name)}</option>`).join('');if(song.charts.some(c=>c.id===h.currentChart()))$('playChart').value=h.currentChart();changeChart();}
 if(songs.some(s=>s.id===h.currentSong()))$('playSong').value=h.currentSong();$('playMode').value=config.mode;ruleText();
